#include "UIAnnotationListPanel.h"
#include "AnnotationManager.h"
#include "AnnotationTypes.h"
#include <imgui.h>
#include <sstream>
#include <iomanip>

AnnotationListAction UIAnnotationListPanel::render(AnnotationManager* manager, int32_t currentTime_ms) {
    AnnotationListAction action;
    if (!visible_ || !manager) return action;

    ImGui::SetNextWindowSize(ImVec2(350, 250), ImGuiCond_FirstUseEver);
    if (ImGui::Begin("Manual Annotations", &visible_)) {
        const auto& annotations = manager->getAnnotations();

        // Auto-generated annotations are not listed
        size_t manualCount = 0;
        for (const auto& ann : annotations) {
            if (!ann.deleted && !ann.isAutoGenerated) {
                ++manualCount;
            }
        }

        if (manualCount == 0) {
            ImGui::TextDisabled("No manual annotations.");
            ImGui::TextDisabled("Right-click on the map to add.");
        } else {
            ImGui::Text("%zu annotation(s)", manualCount);
            ImGui::SameLine(ImGui::GetContentRegionAvail().x - 50);
            if (ImGui::SmallButton("Export")) {
                action.exportRequested = true;
            }
            if (ImGui::IsItemHovered()) {
                ImGui::SetTooltip("Export world-anchored annotations to manual_annotations/ folder");
            }
            ImGui::Separator();

            // Deleting erases from the vector being walked, so it waits until
            // the loop is done.
            uint64_t deleteId = 0;
            if (ImGui::BeginChild("AnnotationList", ImVec2(0, 0), false)) {
                for (const auto& ann : annotations) {
                    if (ann.deleted || ann.isAutoGenerated) continue;

                    ImGui::PushID(static_cast<int>(ann.id));

                    bool isSelected = (manager->getSelectedAnnotationId() == ann.id);

                    if (ImGui::Selectable("##row", isSelected, ImGuiSelectableFlags_AllowItemOverlap, ImVec2(0, 22))) {
                        manager->setSelectedAnnotation(ann.id);
                    }

                    ImGui::SameLine(0, 0);

                    ImGui::Text("%s", getShapeName(ann.shape));

                    ImGui::SameLine();
                    ImVec4 color(ann.color[0], ann.color[1], ann.color[2], ann.color[3]);
                    ImGui::ColorButton("##color", color, ImGuiColorEditFlags_NoTooltip | ImGuiColorEditFlags_NoPicker, ImVec2(16, 16));

                    // Normal text colour, not dimmed, so it stays readable
                    ImGui::SameLine();
                    std::string duration = formatDuration(ann, currentTime_ms);
                    ImGui::TextColored(ImVec4(0.7f, 0.7f, 0.7f, 1.0f), "%s", duration.c_str());

                    // Buttons on the right side
                    ImGui::SameLine(ImGui::GetContentRegionAvail().x - 50);

                    // Edit also snaps the camera to the annotation
                    if (ImGui::SmallButton("Edit")) {
                        action.snapToId = ann.id;
                        action.editId = ann.id;
                        manager->setSelectedAnnotation(ann.id);
                    }

                    ImGui::SameLine();
                    ImGui::PushStyleColor(ImGuiCol_Button, ImVec4(0.6f, 0.1f, 0.1f, 1.0f));
                    ImGui::PushStyleColor(ImGuiCol_ButtonHovered, ImVec4(0.8f, 0.2f, 0.2f, 1.0f));
                    if (ImGui::SmallButton("X")) {
                        deleteId = ann.id;
                    }
                    ImGui::PopStyleColor(2);

                    ImGui::PopID();
                }
            }
            ImGui::EndChild();
            if (deleteId != 0) {
                manager->deleteAnnotation(deleteId);
            }
        }
    }
    ImGui::End();

    return action;
}

const char* UIAnnotationListPanel::getShapeName(AnnotationShape shape) const {
    switch (shape) {
        case AnnotationShape::Circle: return "Circle";
        case AnnotationShape::Rectangle: return "Rectangle";
        case AnnotationShape::Cone: return "Cone";
        case AnnotationShape::Line: return "Line";
        default: return "Unknown";
    }
}

std::string UIAnnotationListPanel::formatDuration(const Annotation& ann, int32_t currentTime_ms) const {
    if (ann.durationType == AnnotationDuration::Encounter) {
        return "Encounter";
    }

    int32_t endTime = ann.creationTimestamp_ms + ann.durationMs;
    int32_t remaining_ms = endTime - currentTime_ms;

    if (remaining_ms <= 0) {
        return "Expired";
    }

    float remaining_sec = remaining_ms / 1000.0f;
    std::ostringstream oss;
    oss << std::fixed << std::setprecision(1) << remaining_sec << "s";
    return oss.str();
}
